| 11+ | $20 each |

**TECHNICAL**

```javascript
// Share referral link
const referralLink = `https://app.com/invite?code=${user.referralCode}`;

// Track with attribution
const trackClick = (code) => {
  analytics.track('referral_click', { code });
  cookie.set('referred_by', code, 30);
};

// Convert signup
const onSignup = async (userData) => {
  const referredBy = cookie.get('referred_by');
  if (referredBy) {
    await createReferral(referredBy, userData.id);
  }
};
```

